#!/usr/bin/env node
/**
 * build-bundle.js
 *
 * Builds a single importable Grafana bundle from the per-dashboard exports.
 *
 * The output is the same shape Grafana produces from
 *   Dashboards > (folder) > Export > "Export for sharing externally"
 * so it can be re-imported on a fresh Grafana with:
 *   Dashboards > Import > Upload JSON file
 * (or programmatically with scripts/import-dashboards.ps1)
 *
 * Datasource references are rewritten to the __inputs placeholder so the
 * importing analyst can map the OpenSearch datasource to whatever it is called
 * on the target instance.
 *
 * Usage: node scripts/build-bundle.js
 */
'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const DASH_DIR = path.join(ROOT, 'dashboards');
const EXP_DIR = path.join(ROOT, 'export');

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8').replace(/^\uFEFF/, ''));
const writeJson = (p, o) => fs.writeFileSync(p, JSON.stringify(o, null, 2) + '\n');

const inventory = readJson(path.join(EXP_DIR, 'inventory.json'));

// The datasource that the dashboards actually query.
const primaryDs = inventory.datasources.find(
  (d) => d.type === 'grafana-opensearch-datasource' && d.indexPattern
);
if (!primaryDs) {
  console.error('No OpenSearch datasource with an index pattern found in export/inventory.json');
  process.exit(1);
}

const DS_PLACEHOLDER = 'DS_OPENSEARCH';

const files = fs.readdirSync(DASH_DIR).filter((f) => f.endsWith('.json')).sort();
const dashboards = [];

for (const file of files) {
  const raw = readJson(path.join(DASH_DIR, file));
  const d = JSON.parse(JSON.stringify(raw.dashboard || raw));

  // Grafana's shareable format drops the server-side id and keeps the uid.
  delete d.id;

  // Rewrite every datasource reference to the placeholder so the bundle is
  // portable across instances where the datasource uid/name differs.
  const remap = (node) => {
    if (!node || typeof node !== 'object') return;
    if (Array.isArray(node)) return node.forEach(remap);
    if (node.datasource && typeof node.datasource === 'object' && node.datasource.uid) {
      if (node.datasource.uid === primaryDs.uid) {
        node.datasource = { type: 'grafana-opensearch-datasource', uid: `$${DS_PLACEHOLDER}` };
      }
    }
    Object.values(node).forEach(remap);
  };
  remap(d.panels);
  remap(d.templating);
  remap(d.annotations);

  d.__inputs = [
    {
      name: DS_PLACEHOLDER,
      label: 'OpenSearch (Wazuh alerts)',
      description: 'OpenSearch datasource holding the wazuh-alerts-4.x-* indices',
      type: 'datasource',
      pluginId: 'grafana-opensearch-datasource',
      pluginName: 'OpenSearch',
    },
  ];
  d.__requires = [
    { type: 'grafana', id: 'grafana', name: 'Grafana', version: inventory.grafanaVersion },
    {
      type: 'datasource',
      id: 'grafana-opensearch-datasource',
      name: 'OpenSearch',
      version: '2.34.0',
    },
  ];
  dashboards.push(d);
}

const bundle = {
  __inputs: [
    {
      name: DS_PLACEHOLDER,
      label: 'OpenSearch (Wazuh alerts)',
      description: 'OpenSearch datasource holding the wazuh-alerts-4.x-* indices',
      type: 'datasource',
      pluginId: 'grafana-opensearch-datasource',
      pluginName: 'OpenSearch',
    },
  ],
  __requires: [
    { type: 'grafana', id: 'grafana', name: 'Grafana', version: inventory.grafanaVersion },
    { type: 'datasource', id: 'grafana-opensearch-datasource', name: 'OpenSearch', version: '2.34.0' },
  ],
  annotations: { list: [] },
  templating: { list: [] },
  folders: [],
  dashboards,
  // Reference copy of the datasource definition, for reference/provisioning.
  datasources: [
    {
      name: primaryDs.name,
      type: primaryDs.type,
      access: 'proxy',
      url: primaryDs.url,
      jsonData: {
        database: primaryDs.indexPattern,
        timeField: primaryDs.timeField,
        interval: primaryDs.interval,
        flavor: 'opensearch',
        version: '2.0.0',
        maxConcurrentShardRequests: 5,
        tlsSkipVerify: true,
      },
    },
  ],
  meta: {
    builtAt: new Date().toISOString(),
    source: inventory.exportedFrom,
    grafanaVersion: inventory.grafanaVersion,
    dashboardCount: dashboards.length,
    note:
      'Generated by scripts/build-bundle.js. Import via Dashboards > Import > Upload JSON file, ' +
      'or with scripts/import-dashboards.ps1.',
  },
};

writeJson(path.join(EXP_DIR, 'grafana-soc-dashboards.bundle.json'), bundle);

console.log(
  `bundle: ${dashboards.length} dashboards, datasource placeholder "${DS_PLACEHOLDER}" -> ${primaryDs.name}`
);
console.log('wrote export/grafana-soc-dashboards.bundle.json');
